     1→import { useState, useEffect } from "react";
     2→import { StyleSheet } from "react-native";
     3→import { Route, Waypoint } from "../types/Route";
     4→import { TAppProps, TController } from "./types";
     5→
     6→export const useController = (props: TAppProps): TController => {
     7→  const [currentRoute, setCurrentRoute] = useState<Route | null>(null);
     8→  const [recordedVideoUri, setRecordedVideoUri] = useState<string | null>(null);
     9→  const [index, setIndex] = useState(0);
    10→
    11→  const generateId = () => Math.random().toString(36).substr(2, 9);
    12→
    13→  // Create a sample route for testing
    14→  useEffect(() => {
    15→    if (!currentRoute) {
    16→      const sampleRoute = {
    17→        id: generateId(),
    18→        waypoints: [
    19→          {
    20→            id: generateId(),
    21→            coordinate: { latitude: 37.7749, longitude: -122.4194 }, // San Francisco
    22→            name: "San Francisco",
    23→            timestamp: Date.now(),
    24→          },
    25→          {
    26→            id: generateId(),
    27→            coordinate: { latitude: 37.8716, longitude: -122.2727 }, // Berkeley
    28→            name: "Berkeley",
    29→            timestamp: Date.now() + 1000,
    30→          },
    31→          {
    32→            id: generateId(),
    33→            coordinate: { latitude: 37.7749, longitude: -122.2521 }, // Oakland
    34→            name: "Oakland",
    35→            timestamp: Date.now() + 2000,
    36→          },
    37→        ],
    38→        metadata: {
    39→          name: "Bay Area Tour",
    40→          description: "Sample route around the Bay Area",
    41→          createdAt: Date.now(),
    42→          updatedAt: Date.now(),
    43→        },
    44→      };
    45→      setCurrentRoute(sampleRoute as Route);
    46→    }
    47→  }, []);
    48→
    49→  const handleSaveRoute = (routeData: Partial<Route>) => {
    50→    const newRoute: Route = {
    51→      id: generateId(),
    52→      waypoints: [],
    53→      totalDistance: 0,
    54→      ...routeData,
    55→      metadata: {
    56→        ...(routeData.metadata || {}),
    57→      },
    58→    } as Route;
    59→
    60→    setCurrentRoute(newRoute);
    61→    // Switch to waypoints tab
    62→    setIndex(0);
    63→  };
    64→
    65→  const handleAddWaypoint = (waypointData: Omit<Waypoint, "id">) => {
    66→    if (!currentRoute) return;
    67→
    68→    const newWaypoint: Waypoint = {
    69→      id: generateId(),
    70→      ...waypointData,
    71→    };
    72→
    73→    setCurrentRoute({
    74→      ...currentRoute,
    75→      waypoints: [...currentRoute.waypoints, newWaypoint],
    76→    });
    77→  };
    78→
    79→  const handleDeleteWaypoint = (waypointId: string) => {
    80→    if (!currentRoute) return;
    81→
    82→    setCurrentRoute({
    83→      ...currentRoute,
    84→      waypoints: currentRoute.waypoints.filter((wp) => wp.id !== waypointId),
    85→    });
    86→  };
    87→
    88→  const handleUpdateWaypoint = (
    89→    waypointId: string,
    90→    updates: Partial<Waypoint>
    91→  ) => {
    92→    if (!currentRoute) return;
    93→
    94→    setCurrentRoute({
    95→      ...currentRoute,
    96→      waypoints: currentRoute.waypoints.map((wp) =>
    97→        wp.id === waypointId ? { ...wp, ...updates } : wp
    98→      ),
    99→    });
   100→  };
   101→
   102→  const handleVideoCreated = (videoUri: string) => {
   103→    setRecordedVideoUri(videoUri);
   104→    setIndex(2); // Switch to export tab
   105→  };
   106→
   107→  const routes = [
   108→    {
   109→      key: "create",
   110→      title: "Create Route",
   111→      focusedIcon: "map-marker-path",
   112→      unfocusedIcon: "map-marker-path",
   113→    },
   114→    {
   115→      key: "animate",
   116→      title: "Animate",
   117→      focusedIcon: "play",
   118→      unfocusedIcon: "play-outline",
   119→    },
   120→    {
   121→      key: "export",
   122→      title: "Export",
   123→      focusedIcon: "share",
   124→      unfocusedIcon: "share-outline",
   125→    },
   126→  ];
   127→
   128→  const styles = StyleSheet.create({
   129→    scene: {
   130→      flex: 1,
   131→      backgroundColor: "#f5f5f5",
   132→    },
   133→    emptyState: {
   134→      flex: 1,
   135→      justifyContent: "center",
   136→      alignItems: "center",
   137→      padding: 20,
   138→    },
   139→  });
   140→
   141→  return {
   142→    currentRoute,
   143→    recordedVideoUri,
   144→    index,
   145→    setIndex,
   146→    handleSaveRoute,
   147→    handleAddWaypoint,
   148→    handleDeleteWaypoint,
   149→    handleUpdateWaypoint,
   150→    handleVideoCreated,
   151→    routes,
   152→    styles,
   153→  };
   154→};
