     1→import { useState } from "react";
     2→import { VideoExportService } from "@services/VideoExportService";
     3→import { TProps, TController } from "./types";
     4→
     5→export const useController = (props: TProps): TController => {
     6→  const { videoUri } = props;
     7→
     8→  const [isExporting, setIsExporting] = useState(false);
     9→  const [exportProgress, setExportProgress] = useState(0);
    10→  const [isSharing, setIsSharing] = useState(false);
    11→
    12→  const exportService = new VideoExportService();
    13→
    14→  const handleSaveToGallery = async () => {
    15→    try {
    16→      setIsExporting(true);
    17→      setExportProgress(0);
    18→
    19→      // Simulate progress updates
    20→      const progressInterval = setInterval(() => {
    21→        setExportProgress((prev) => Math.min(prev + 0.1, 0.9));
    22→      }, 200);
    23→
    24→      const albumName = "Travel Route Videos";
    25→      const asset = await exportService.saveVideoToGallery(videoUri, albumName);
    26→
    27→      clearInterval(progressInterval);
    28→      setExportProgress(1);
    29→
    30→      setTimeout(() => {
    31→        setIsExporting(false);
    32→        setExportProgress(0);
    33→      }, 1000);
    34→
    35→      console.log("Video saved:", asset);
    36→    } catch (error) {
    37→      exportService.handleError(error as Error, "save video");
    38→      setIsExporting(false);
    39→      setExportProgress(0);
    40→    }
    41→  };
    42→
    43→  const handleShareVideo = async () => {
    44→    try {
    45→      setIsSharing(true);
    46→      await exportService.shareVideo(videoUri);
    47→    } catch (error) {
    48→      exportService.handleError(error as Error, "share video");
    49→    } finally {
    50→      setIsSharing(false);
    51→    }
    52→  };
    53→
    54→  const getStorageInfo = async () => {
    55→    const info = await exportService.getStorageInfo();
    56→    if (info) {
    57→      console.log("Storage info:", info);
    58→    }
    59→  };
    60→
    61→  return {
    62→    isExporting,
    63→    exportProgress,
    64→    isSharing,
    65→    exportService,
    66→    handleSaveToGallery,
    67→    handleShareVideo,
    68→    getStorageInfo,
    69→  };
    70→};
